#pragma once
#include <usp_lcd_navigation_controller.h>
#include "esphome/components/usp_spotify_auth/playback_worker_engine.h"
#include "esphome/components/usp_spotify_auth/mode_control_policy.h"
#include <cstdint>
#include <cstdio>

namespace usp_spotify_modes_modal {
constexpr uint32_t FACTS_TTL_MS=usp_spotify_modes::FACTS_TTL_MS;
struct Widgets {lv_obj_t *root,*title,*status,*close,*shuffle,*repeat_off,*repeat_context,*repeat_track;};
inline const char *pick(unsigned lang,const char *ua,const char *ru,const char *en){return lang==1?ru:lang==2?en:ua;}
inline void enabled(lv_obj_t *widget,bool allowed){const bool disabled=lv_obj_has_state(widget,LV_STATE_DISABLED);if(allowed&&disabled)lv_obj_remove_state(widget,LV_STATE_DISABLED);else if(!allowed&&!disabled)lv_obj_add_state(widget,LV_STATE_DISABLED);}
inline bool base(const usp_spotify_playback_worker::PlaybackState &state,usp_spotify_tokens::Phase phase,uint32_t now){const auto&s=state.snapshot;return phase==usp_spotify_tokens::Phase::CONNECTED&&state.kind==usp_spotify_playback::ResponseKind::JSON&&s.valid&&s.mode_state_known&&s.device_active&&!s.restricted&&uint32_t(now-state.updated_at)<FACTS_TTL_MS;}
inline bool shuffle_allowed(const usp_spotify_playback_worker::PlaybackState &state,usp_spotify_tokens::Phase phase,uint32_t now){return base(state,phase,now)&&state.snapshot.shuffle.known&&state.snapshot.shuffle.allowed;}
inline bool permission(const usp_spotify_playback::Permission &value){return value.known&&value.allowed;}
inline usp_spotify_modes::Repeat current_repeat(const usp_spotify_playback::PlaybackSnapshot&s){return s.repeat_state==usp_spotify_playback::RepeatState::CONTEXT?usp_spotify_modes::Repeat::CONTEXT:s.repeat_state==usp_spotify_playback::RepeatState::TRACK?usp_spotify_modes::Repeat::TRACK:usp_spotify_modes::Repeat::OFF;}
inline bool repeat_allowed(const usp_spotify_playback_worker::PlaybackState &state,usp_spotify_tokens::Phase phase,uint32_t now,usp_spotify_modes::Repeat target){if(!base(state,phase,now))return false;const auto&s=state.snapshot;const auto current=current_repeat(s);if(current==target)return false;const bool leave=current==usp_spotify_modes::Repeat::CONTEXT?permission(s.repeat_context):current==usp_spotify_modes::Repeat::TRACK?permission(s.repeat_track):true;const bool enter=target==usp_spotify_modes::Repeat::CONTEXT?permission(s.repeat_context):target==usp_spotify_modes::Repeat::TRACK?permission(s.repeat_track):true;return leave&&enter;}
inline const char *repeat_name(usp_spotify_playback::RepeatState value,unsigned lang){if(value==usp_spotify_playback::RepeatState::CONTEXT)return pick(lang,"КОНТЕКСТ","КОНТЕКСТ","CONTEXT");if(value==usp_spotify_playback::RepeatState::TRACK)return pick(lang,"ТРЕК","ТРЕК","TRACK");return pick(lang,"ВИМК","ВЫКЛ","OFF");}
inline void present(const Widgets&w,const usp_spotify_playback_worker::PlaybackState&state,usp_spotify_tokens::Phase phase,uint32_t now,unsigned lang){lang=lang<3?lang:0;usp_lcd_navigation::label_text(w.title,pick(lang,"Режими Spotify","Режимы Spotify","Spotify modes"));usp_lcd_navigation::button_text(w.close,pick(lang,"ЗАКРИТИ","ЗАКРЫТЬ","CLOSE"));usp_lcd_navigation::button_text(w.repeat_off,pick(lang,"ВИМК","ВЫКЛ","OFF"));usp_lcd_navigation::button_text(w.repeat_context,pick(lang,"КОНТЕКСТ","КОНТЕКСТ","CONTEXT"));usp_lcd_navigation::button_text(w.repeat_track,pick(lang,"ТРЕК","ТРЕК","TRACK"));const bool fresh=base(state,phase,now);if(!fresh){usp_lcd_navigation::label_text(w.status,pick(lang,"Стан недоступний","Состояние недоступно","State unavailable"));usp_lcd_navigation::button_text(w.shuffle,pick(lang,"Перемішування","Перемешивание","Shuffle"));for(auto*button:{w.shuffle,w.repeat_off,w.repeat_context,w.repeat_track})enabled(button,false);return;}const auto&s=state.snapshot;usp_lcd_navigation::button_text(w.shuffle,s.shuffle_state?pick(lang,"Перемішування: УВІМК","Перемешивание: ВКЛ","Shuffle: ON"):pick(lang,"Перемішування: ВИМК","Перемешивание: ВЫКЛ","Shuffle: OFF"));char status[96]{};std::snprintf(status,sizeof(status),"%s · %s",pick(lang,"Повтор","Повтор","Repeat"),repeat_name(s.repeat_state,lang));usp_lcd_navigation::label_text(w.status,status);enabled(w.shuffle,shuffle_allowed(state,phase,now));enabled(w.repeat_off,repeat_allowed(state,phase,now,usp_spotify_modes::Repeat::OFF));enabled(w.repeat_context,repeat_allowed(state,phase,now,usp_spotify_modes::Repeat::CONTEXT));enabled(w.repeat_track,repeat_allowed(state,phase,now,usp_spotify_modes::Repeat::TRACK));}
}  // namespace usp_spotify_modes_modal
